// --- Einstellungen ---
#define NUM_LIGHTS 5
#define MAX_DIST 50.0
#define FOG_DENSITY 0.08
#define LIGHT_INTENSITY 3.5

// --- Noise Funktionen (für Nebel und Bodenstruktur) ---

// Einfacher Hash für Pseudo-Zufall
float hash(float n) {
    return fract(sin(n) * 43758.5453123);
}

// 3D Noise Funktion (Value Noise)
float noise(vec3 x) {
    vec3 p = floor(x);
    vec3 f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    float n = p.x + p.y * 57.0 + 113.0 * p.z;
    float res = mix(mix(mix(hash(n + 0.0), hash(n + 1.0), f.x),
                        mix(hash(n + 57.0), hash(n + 58.0), f.x), f.y),
                    mix(mix(hash(n + 113.0), hash(n + 114.0), f.x),
                        mix(hash(n + 170.0), hash(n + 171.0), f.x), f.y), f.z);
    return res;
}

// Fractal Brownian Motion (für detaillierteren Nebel/Boden)
float fbm(vec3 p) {
    float f = 0.0;
    f += 0.5000 * noise(p); p *= 2.02;
    f += 0.2500 * noise(p); p *= 2.03;
    f += 0.1250 * noise(p); p *= 2.01;
    return f;
}

// --- Lichtdefinitionen ---
struct Light {
    vec3 pos;
    vec3 dir;
    vec3 color;
    float angle; // Kosinus des halben Öffnungswinkels
};

Light lights[NUM_LIGHTS];

void setupLights() {
    // Lichtpositionen und Farben ähnlich dem Bild
    // Links: Blau
    for(int i = 0; i < NUM_LIGHTS; i++){
            lights[i] = Light(light_param[i].position, normalize(light_param[i].direction), light_param[i].c, light_param[i].angle);
    }
    /*
    lights[0] = Light(vec3(-5.0, 6.0, 2.0), normalize(vec3(1.0, -1.5, 0.0)), vec3(0.1, 0.3, 1.0), 0.92);
    // Mitte-Links: Pink/Magenta
    lights[1] = Light(vec3(-2.0, 6.5, 3.0), normalize(vec3(0.4, -1.8, 0.0)), vec3(1.0, 0.1, 0.8), 0.94);
    // Mitte: Blau
    lights[2] = Light(vec3(0.5, 7.0, 2.5), normalize(vec3(0.0, -2.0, 0.0)), vec3(0.2, 0.4, 1.0), 0.95);
    // Mitte-Rechts: Pink
    lights[3] = Light(vec3(3.0, 6.5, 3.0), normalize(vec3(-0.3, -1.7, 0.0)), vec3(0.9, 0.2, 0.9), 0.93);
    // Rechts: Pink/Violett
    lights[4] = Light(vec3(6.0, 6.0, 2.0), normalize(vec3(-1.0, -1.4, 0.0)), vec3(0.8, 0.1, 1.0), 0.92);
    */
}

// --- Volumetrisches Licht ---

// Berechnet den Beitrag eines einzelnen Scheinwerfers an einem Punkt im Raum
vec3 getSpotlightContrib(vec3 p, Light l) {
    vec3 lightToPoint = p - l.pos;
    float dist = length(lightToPoint);
    vec3 dir = lightToPoint / dist;

    // Prüfen, ob der Punkt im Lichtkegel liegt
    float cosAngle = dot(dir, l.dir);
    float spotEffect = smoothstep(l.angle, l.angle + 0.05,  cosAngle) * (cosAngle);

    // Distanzabfall
    float attenuation = 1.0 / (1.0 + dist * 0.1 + dist * dist * 0.02);

    // Nebel-Struktur (Noise)
    float fogNoise = fbm(p * 0.5 + vec3(0.0, iTime * 0.2, 0.0)); // Bewegender Nebel
    fogNoise = mix(0.5, 1.0, fogNoise);

    return l.color * spotEffect * attenuation * fogNoise * LIGHT_INTENSITY;
}

// Raymarching für volumetrischen Nebel
vec3 traceFog(vec3 ro, vec3 rd, float maxT) {
    vec3 fogColor = vec3(0.0);
    float t = 0.0;
    // Wenige Schritte für Performance, mit Dithering für Glätte
    int numSteps = 40;
    float stepSize = maxT / float(numSteps);

    // Dithering des Startpunkts, um Banding zu vermeiden
    t += hash(dot(rd.xy, vec2(12.9898, 78.233)) + iTime) * stepSize;

    for (int i = 0; i < numSteps; ++i) {
        if (t > maxT) break;
        vec3 p = ro + rd * t;

        vec3 currentStepLight = vec3(0.0);
        for (int j = 0; j < NUM_LIGHTS; ++j) {
            currentStepLight += getSpotlightContrib(p, lights[j]);
        }

        // Lichtquelle direkt sichtbar machen (Lens Flare Fake)
        for (int j = 0; j < NUM_LIGHTS; ++j) {
            vec3 toLight = lights[j].pos - ro;
            float dToLight = length(toLight);
            float proj = dot(normalize(toLight), rd);
            // Wenn wir fast direkt in das Licht schauen
            if(proj > 0.99 && t > dToLight - stepSize && t < dToLight + stepSize) {
                 currentStepLight += lights[j].color * 50.0 * pow(proj, 256.0) / (dToLight*dToLight);
            }
        }

        fogColor += currentStepLight * FOG_DENSITY * stepSize;
        t += stepSize;
    }
    return fogColor;
}


// --- Boden und Szene ---

// Bodenhöhe
const float floorHeight = -1.5;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    setupLights();

    // UV-Koordinaten normalisieren (-1 bis 1, aspect corrected)
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Kamera Setup
    vec3 ro = vec3(0.0, 1.0, -6.0); // Kameraposition
    vec3 ta = vec3(0.0, 1.0, 0.0);  // Zielpunkt
    vec3 fwd = normalize(ta - ro);
    vec3 right = normalize(cross(fwd, vec3(0.0, 1.0, 0.0)));
    vec3 up = cross(right, fwd);
    vec3 rd = normalize(fwd + uv.x * right + uv.y * up); // Strahlrichtung

    vec3 finalColor = vec3(0.0);

    // --- Bodenschnittpunkt ---
    float tFloor = (floorHeight - ro.y) / rd.y;

    if (tFloor > 0.0 && tFloor < MAX_DIST) {
        // Wir treffen den Boden
        vec3 floorPos = ro + rd * tFloor;

        // Bodenstruktur (Bump Map für Reflexionen)
        // Wir verzerren die Position, die für die Reflexion genutzt wird
        vec3 distortedPos = floorPos;
        distortedPos.x += fbm(floorPos * 2.0) * 0.2;
        distortedPos.z += fbm(floorPos * 1.5 + vec3(0.0, 0.0, 1.0)) * 0.3;

        // Basis-Bodenfarbe (dunkel)
        vec3 floorBaseColor = vec3(0.02);

        // Direkte Beleuchtung auf dem Boden (Lichtflecken)
        vec3 floorLight = vec3(0.0);
        for(int i=0; i<NUM_LIGHTS; ++i) {
             // Einfacher Abstandsbasierten Lichtfleck auf dem Boden
             vec3 lightDirToFloor = normalize(floorPos - lights[i].pos);
             float spot = smoothstep(lights[i].angle-0.05, lights[i].angle+0.05, dot(lightDirToFloor, lights[i].dir));
             float dist = length(lights[i].pos - floorPos);
             float atten = 1.0 / (1.0 + dist*0.5 + dist*dist*0.1);
             floorLight += lights[i].color * spot * atten * 2.0;
        }
        floorBaseColor += floorLight;

        // Reflexion berechnen
        vec3 normal = vec3(0.0, 1.0, 0.0);
        // Normalen-Störung für welligen Effekt
        float bump = fbm(distortedPos*3.0);
        normal = normalize(normal + vec3(dFdx(bump), 0.0, dFdy(bump)) * 0.2);

        vec3 reflectDir = reflect(rd, normal);

        // Volumetrisches Licht des reflektierten Strahls berechnen
        vec3 reflectedSky = traceFog(floorPos, reflectDir, MAX_DIST - tFloor);

        // Fresnel-Effekt (Reflexion ist stärker bei flachem Winkel)
        float fresnel = pow(1.0 - max(0.0, dot(-rd, normal)), 4.0);
        fresnel = mix(0.2, 0.9, fresnel); // Basis-Reflexivität + Fresnel

        finalColor = mix(floorBaseColor, reflectedSky, fresnel);

    } else {
        // Wir treffen den "Himmel" / Hintergrund
        finalColor = traceFog(ro, rd, MAX_DIST);
        // Sehr dunkler Hintergrundverlauf
        finalColor += vec3(0.01, 0.01, 0.02) * (1.0 - uv.y);
    }

    // --- Post-Processing ---
    // Vignette
    vec2 q = fragCoord.xy / iResolution.xy;
    finalColor *= 0.5 + 0.5*pow( 16.0*q.x*q.y*(1.0-q.x)*(1.0-q.y), 0.25 );

    // Tone Mapping (Reinhard) und Gamma-Korrektur
    finalColor = finalColor / (1.0 + finalColor);
    finalColor = pow(finalColor, vec3(1.0 / 2.2));

    fragColor = vec4(finalColor, 1.0);
}

// @param rotationSpeed float 1.0 [0.0, 5.0] "Rotation speed"
// @param beamIntensity float 0.4 [0.1, 1.0] "Beam intensity"

const beamVertexShader = `
    varying vec3 vNormal;
    varying vec3 vWorldPosition;
    void main() {
        vNormal = normalize(normalMatrix * normal);
        vec4 worldPosition = modelMatrix * vec4(position, 1.0);
        vWorldPosition = worldPosition.xyz;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
`;

const beamFragmentShader = `
    varying vec3 vNormal;
    varying vec3 vWorldPosition;
    uniform vec3 color;
    uniform float intensity;

    void main() {
        float viewAngle = dot(vNormal, vec3(0.0, 0.0, 1.0));
        float falloff = pow(1.0 - abs(viewAngle), 3.0);
        float yAlpha = smoothstep(-5.0, 5.0, vWorldPosition.y + 2.0);
        gl_FragColor = vec4(color, falloff * intensity * yAlpha);
    }
`;

function setup(THREE, canvas, params) {
    const scene = new THREE.Scene();
    scene.fog = new THREE.Fog(0x000000, 5, 25);

    const camera = new THREE.PerspectiveCamera(75, canvas.width / canvas.height, 0.1, 1000);
    camera.position.set(0, 2, 8);

    const renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true });
    renderer.setSize(canvas.width, canvas.height);

    // Boden
    const floorGeo = new THREE.PlaneGeometry(30, 30);
    const floorMat = new THREE.MeshStandardMaterial({ 
        color: 0x111111, 
        roughness: 0.1, 
        metalness: 0.5 
    });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -2;
    scene.add(floor);

    // Lichtquellen & Strahlen
    const lightsData = [
        { pos: [-5, 5, 0], color: 0x2266ff, rot: -0.4 },
        { pos: [-2, 5.5, 0], color: 0xff22aa, rot: -0.1 },
        { pos: [0.5, 6, 0], color: 0x3388ff, rot: 0.05 },
        { pos: [3, 5.5, 0], color: 0xff33bb, rot: 0.2 },
        { pos: [6, 5, 0], color: 0xaa22ff, rot: 0.5 }
    ];

    const beams = [];
    const spotLights = [];

    lightsData.forEach(data => {
        const spotLight = new THREE.SpotLight(data.color, 50);
        spotLight.position.set(data.pos[0], data.pos[1], data.pos[2]);
        spotLight.angle = 0.3;
        spotLight.penumbra = 0.5;
        scene.add(spotLight);

        const target = new THREE.Object3D();
        target.position.set(data.pos[0] + (data.rot * 5), -2, 0);
        scene.add(target);
        spotLight.target = target;
        spotLights.push(spotLight);

        const beamGeo = new THREE.ConeGeometry(1.5, 12, 32, 1, true);
        const beamMat = new THREE.ShaderMaterial({
            uniforms: {
                color: { value: new THREE.Color(data.color) },
                intensity: { value: params.beamIntensity || 0.4 }
            },
            vertexShader: beamVertexShader,
            fragmentShader: beamFragmentShader,
            transparent: true,
            blending: THREE.AdditiveBlending,
            side: THREE.DoubleSide,
            depthWrite: false
        });

        const beam = new THREE.Mesh(beamGeo, beamMat);
        beam.position.set(data.pos[0], data.pos[1] - 4, data.pos[2]);
        beam.rotation.z = data.rot;
        beam.userData.baseRotation = data.rot;

        scene.add(beam);
        beams.push(beam);
    });

    const ambient = new THREE.AmbientLight(0x050505);
    scene.add(ambient);

    return { scene, camera, renderer, beams, spotLights };
}

function animate(time, deltaTime, params, objects) {
    const { beams, renderer, scene, camera } = objects;
    const speed = params.rotationSpeed || 1.0;

    beams.forEach((beam, i) => {
        beam.rotation.z = beam.userData.baseRotation + Math.sin(time * speed + i) * 0.15;
        beam.material.uniforms.intensity.value = (params.beamIntensity || 0.4) + Math.sin(time * 2.0 + i) * 0.1;
    });

    renderer.render(scene, camera);
}

// Stage Lighting Simulator
// A Three.js scene demonstrating concert/stage lighting effects
//
// @param cameraSpeed float 0.002 [0, 0.1] "Camera rotation speed"
// @param movingHeadSpeed float 0.5 [0.1, 2.0] "Moving head animation speed"
// @param ledBarSpeed float 0.3 [0.1, 1.0] "LED bar color cycle speed"
// @param hazeOpacity float 0.4 [0, 1] "Haze particle opacity"
// @param blinderFlashRate float 2.0 [0.5, 5.0] "Blinder flash rate"
// @param spotIntensity float 50 [10, 100] "Spot light intensity"
// @param movingHeadIntensity float 80 [20, 150] "Moving head intensity"
// @param autoRotate int 1 [0, 1] "Camera auto-rotation"
// @param cameraAngle int 60 [0, 180] "Camera auto-rotation"
// @param cameraPos vec3 [0.0,8.0,25.0] [-25,25]
// @param cameralookAt vec3 [0.0,3.0,0.0] [-25,25]

function updateCamera(camera, angle){
  camera.position.set(params.cameraPos[0], params.cameraPos[1], params.cameraPos[2]);
  camera.lookAt(params.cameralookAt[0], params.cameralookAt[1], params.cameralookAt[2]);
  camera.fov = angle;
  camera.updateProjectionMatrix();
}

function setup(THREE, canvas, params, channels, mouse) {
  // Scene setup
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050508);
  scene.fog = new THREE.FogExp2(0x050508, 0.015);

  const camera = new THREE.PerspectiveCamera(params.cameraAngle, canvas.width / canvas.height, 0.1, 1000);
  updateCamera(camera, params.cameraAngle);
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, preserveDrawingBuffer: true });
  renderer.setSize(canvas.width, canvas.height, false);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;

  // Ambient light (very dim)
  const ambient = new THREE.AmbientLight(0x111122, 0.3);
  scene.add(ambient);

  // Stage floor
  const stageGeo = new THREE.BoxGeometry(30, 0.5, 20);
  const stageMat = new THREE.MeshStandardMaterial({
    color: 0x1a1a1a,
    roughness: 0.8,
    metalness: 0.2
  });
  const stage = new THREE.Mesh(stageGeo, stageMat);
  stage.position.y = -0.25;
  stage.receiveShadow = true;
  scene.add(stage);

  // Back wall
  const wallGeo = new THREE.BoxGeometry(30, 15, 0.5);
  const wallMat = new THREE.MeshStandardMaterial({ color: 0x0a0a0a, roughness: 0.9 });
  const backWall = new THREE.Mesh(wallGeo, wallMat);
  backWall.position.set(0, 7, -10);
  backWall.receiveShadow = true;
  scene.add(backWall);

  // Truss system
  const trussMat = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.8, roughness: 0.3 });

  function createTruss(length) {
    const group = new THREE.Group();
    const radius = 0.08;

    const positions = [[-0.3, 0.3], [0.3, 0.3], [-0.3, -0.3], [0.3, -0.3]];

    positions.forEach(([y, z]) => {
      const geo = new THREE.CylinderGeometry(radius, radius, length, 8);
      geo.rotateZ(Math.PI / 2);
      const mesh = new THREE.Mesh(geo, trussMat);
      mesh.position.set(0, y, z);
      group.add(mesh);
    });

    const braceCount = Math.floor(length / 2);
    for (let i = 0; i <= braceCount; i++) {
      const x = -length/2 + i * (length / braceCount);
      const ringGeo = new THREE.TorusGeometry(0.35, 0.04, 8, 4);
      ringGeo.rotateY(Math.PI / 2);
      const ring = new THREE.Mesh(ringGeo, trussMat);
      ring.position.x = x;
      group.add(ring);
    }

    return group;
  }

  // Trusses
  const frontTruss = createTruss(28);
  frontTruss.position.set(0, 10, 5);
  scene.add(frontTruss);

  const backTruss = createTruss(28);
  backTruss.position.set(0, 12, -5);
  scene.add(backTruss);

  const leftTruss = createTruss(12);
  leftTruss.rotation.y = Math.PI / 2;
  leftTruss.position.set(-14, 10, 0);
  scene.add(leftTruss);

  const rightTruss = createTruss(12);
  rightTruss.rotation.y = Math.PI / 2;
  rightTruss.position.set(14, 10, 0);
  scene.add(rightTruss);

  // Arrays to store animated lights
  const movingHeads = [];
  const spotLights = [];
  const barLights = [];

  // Helper to create volumetric cone
  function createLightCone(color, angle = 0.4, length = 12) {
    const coneGeo = new THREE.ConeGeometry(Math.tan(angle) * length, length, 32, 1, true);
    const coneMat = new THREE.MeshBasicMaterial({
      color: color,
      transparent: true,
      opacity: 0.08,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
      depthWrite: false
    });
    const cone = new THREE.Mesh(coneGeo, coneMat);
    cone.rotation.x = Math.PI;
    cone.position.y = -length / 2;
    return cone;
  }

  // Create fixture housing
  function createFixtureHousing(type = 'spot') {
    const group = new THREE.Group();
    const housingMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, metalness: 0.7, roughness: 0.3 });

    if (type === 'moving') {
      const yokeGeo = new THREE.BoxGeometry(0.6, 0.8, 0.15);
      const yoke = new THREE.Mesh(yokeGeo, housingMat);
      group.add(yoke);

      const headGroup = new THREE.Group();
      const headGeo = new THREE.CylinderGeometry(0.35, 0.4, 0.7, 16);
      headGeo.rotateX(Math.PI / 2);
      const head = new THREE.Mesh(headGeo, housingMat);
      headGroup.add(head);

      const lensGeo = new THREE.CircleGeometry(0.3, 16);
      const lensMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.9 });
      const lens = new THREE.Mesh(lensGeo, lensMat);
      lens.position.z = 0.36;
      headGroup.add(lens);

      headGroup.position.y = -0.4;
      group.add(headGroup);
      group.headGroup = headGroup;
      group.lens = lens;
    } else if (type === 'spot') {
      const bodyGeo = new THREE.CylinderGeometry(0.25, 0.35, 0.8, 12);
      const body = new THREE.Mesh(bodyGeo, housingMat);
      body.rotation.x = Math.PI;
      group.add(body);

      const lensGeo = new THREE.CircleGeometry(0.33, 16);
      const lensMat = new THREE.MeshBasicMaterial({ color: 0xffffcc });
      const lens = new THREE.Mesh(lensGeo, lensMat);
      lens.rotation.x = Math.PI / 2;
      lens.position.y = -0.41;
      group.add(lens);
    } else if (type === 'par') {
      const bodyGeo = new THREE.CylinderGeometry(0.2, 0.2, 0.4, 12);
      const body = new THREE.Mesh(bodyGeo, housingMat);
      body.rotation.x = Math.PI / 2;
      group.add(body);
    }

    return group;
  }

  // SPOT LIGHTS - Front truss
  const spotColors = [0xff4444, 0x44ff44, 0x4444ff, 0xffff44, 0xff44ff, 0x44ffff];
  for (let i = 0; i < 6; i++) {
    const x = -12 + i * 4.8;
    const color = spotColors[i];

    const fixture = createFixtureHousing('spot');
    fixture.position.set(x, 9.5, 5);
    fixture.rotation.x = 0.3;
    scene.add(fixture);

    const spot = new THREE.SpotLight(color, params.spotIntensity, 25, 0.4, 0.5, 1);
    spot.position.set(x, 9.2, 5);
    spot.target.position.set(x * 0.3, 0, -2);
    scene.add(spot);
    scene.add(spot.target);

    const cone = createLightCone(color, 0.4, 10);
    cone.position.set(x, 9.2, 5);
    cone.rotation.x = 0.3;
    scene.add(cone);

    spotLights.push({ light: spot, cone, fixture, baseX: x, color });
  }

  // MOVING HEADS - Back truss
  const movingColors = [0xff0066, 0x00ffff, 0xff6600, 0x00ff66, 0x6600ff, 0xffff00];
  for (let i = 0; i < 6; i++) {
    const x = -10 + i * 4;
    const color = movingColors[i];

    const fixture = createFixtureHousing('moving');
    fixture.position.set(x, 11.5, -5);
    scene.add(fixture);

    const spot = new THREE.SpotLight(color, params.movingHeadIntensity, 30, 0.25, 0.3, 1);
    spot.position.set(x, 10.8, -5);
    spot.castShadow = true;
    spot.shadow.mapSize.width = 512;
    spot.shadow.mapSize.height = 512;
    scene.add(spot);
    scene.add(spot.target);

    const cone = createLightCone(color, 0.25, 14);
    scene.add(cone);

    movingHeads.push({
      light: spot,
      cone,
      fixture,
      baseX: x,
      phase: i * Math.PI / 3,
      color
    });
  }

  // LED BARS
  function createLEDBar(width, segments) {
    const group = new THREE.Group();
    const housingGeo = new THREE.BoxGeometry(width, 0.15, 0.2);
    const housingMat = new THREE.MeshStandardMaterial({ color: 0x111111, metalness: 0.8 });
    const housing = new THREE.Mesh(housingGeo, housingMat);
    group.add(housing);

    const segmentWidth = width / segments;
    const lights = [];

    for (let i = 0; i < segments; i++) {
      const x = -width/2 + segmentWidth/2 + i * segmentWidth;
      const ledGeo = new THREE.PlaneGeometry(segmentWidth * 0.8, 0.1);
      const ledMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
      const led = new THREE.Mesh(ledGeo, ledMat);
      led.position.set(x, 0.08, 0);
      led.rotation.x = -Math.PI / 2;
      group.add(led);

      const pointLight = new THREE.PointLight(0xffffff, 2, 4);
      pointLight.position.set(x, 0.2, 0);
      group.add(pointLight);

      lights.push({ mesh: led, light: pointLight, index: i });
    }

    group.lights = lights;
    return group;
  }

  const frontBar1 = createLEDBar(8, 12);
  frontBar1.position.set(-8, 0.1, 8);
  frontBar1.rotation.x = -0.2;
  scene.add(frontBar1);
  barLights.push({ bar: frontBar1, phase: 0 });

  const frontBar2 = createLEDBar(8, 12);
  frontBar2.position.set(8, 0.1, 8);
  frontBar2.rotation.x = -0.2;
  scene.add(frontBar2);
  barLights.push({ bar: frontBar2, phase: Math.PI });

  const backBar = createLEDBar(20, 24);
  backBar.position.set(0, 0.1, -8);
  backBar.rotation.x = 0.8;
  scene.add(backBar);
  barLights.push({ bar: backBar, phase: 0, isBack: true });

  // WASH LIGHTS
  const washColors = [0xff3366, 0x3366ff, 0xff3366, 0x3366ff];
  const washPositions = [[-14, 10, 4], [-14, 10, -4], [14, 10, 4], [14, 10, -4]];

  washPositions.forEach((pos, i) => {
    const color = washColors[i];
    const wash = new THREE.SpotLight(color, 40, 25, 0.8, 0.8, 1);
    wash.position.set(...pos);
    wash.target.position.set(0, 0, pos[2] * 0.5);
    scene.add(wash);
    scene.add(wash.target);

    const cone = createLightCone(color, 0.8, 12);
    cone.position.set(...pos);
    cone.rotation.z = i < 2 ? 0.5 : -0.5;
    scene.add(cone);
  });

  // BLINDERS
  function createBlinder() {
    const group = new THREE.Group();
    const housingGeo = new THREE.BoxGeometry(2, 0.8, 0.4);
    const housingMat = new THREE.MeshStandardMaterial({ color: 0x222222, metalness: 0.7 });
    const housing = new THREE.Mesh(housingGeo, housingMat);
    group.add(housing);

    const cells = [];
    for (let i = 0; i < 4; i++) {
      const x = -0.75 + i * 0.5;
      const cellGeo = new THREE.CircleGeometry(0.18, 16);
      const cellMat = new THREE.MeshBasicMaterial({ color: 0xffffcc });
      const cell = new THREE.Mesh(cellGeo, cellMat);
      cell.position.set(x, 0, 0.21);
      group.add(cell);

      const light = new THREE.SpotLight(0xffffcc, 0, 15, 0.6, 0.5, 1);
      light.position.set(x, 0, 0.3);
      light.target.position.set(x, -5, 10);
      group.add(light);
      group.add(light.target);

      cells.push({ mesh: cell, light });
    }

    group.cells = cells;
    return group;
  }

  const blinder = createBlinder();
  blinder.position.set(0, 9.5, 5.3);
  blinder.rotation.x = 0.4;
  scene.add(blinder);

  // Haze particles
  const hazeGeo = new THREE.BufferGeometry();
  const hazeCount = 2000;
  const hazePositions = new Float32Array(hazeCount * 3);

  for (let i = 0; i < hazeCount; i++) {
    hazePositions[i * 3] = (Math.random() - 0.5) * 30;
    hazePositions[i * 3 + 1] = Math.random() * 15;
    hazePositions[i * 3 + 2] = (Math.random() - 0.5) * 25;
  }

  hazeGeo.setAttribute('position', new THREE.BufferAttribute(hazePositions, 3));
  const hazeMat = new THREE.PointsMaterial({
    color: 0x666688,
    size: 0.08,
    transparent: true,
    opacity: params.hazeOpacity,
    blending: THREE.AdditiveBlending
  });
  const haze = new THREE.Points(hazeGeo, hazeMat);
  scene.add(haze);

  return {
    scene,
    camera,
    renderer,
    objects: {
      movingHeads,
      spotLights,
      barLights,
      blinder,
      haze,
      hazeMat,
      hazeCount,
      camera,
      cameraAngle: params.cameraAngle
    }
  };
}

function animate(time, delta, params, objects, mouse, channels) {
  const { movingHeads, spotLights, barLights, blinder, haze, hazeMat, hazeCount, camera } = objects;
  const THREE = window.THREE;

  // Update haze opacity from params
  hazeMat.opacity = params.hazeOpacity;

  // Animate moving heads
  movingHeads.forEach((mh, i) => {
    const speed = params.movingHeadSpeed;
    const pan = Math.sin(time * speed + mh.phase) * 0.8;
    const tilt = Math.sin(time * speed * 1.4 + mh.phase * 1.5) * 0.3 + 0.5;

    if (mh.fixture.headGroup) {
      mh.fixture.headGroup.rotation.x = tilt;
      mh.fixture.rotation.y = pan;
    }

    const targetX = mh.baseX + Math.sin(time * speed + mh.phase) * 8;
    const targetZ = Math.sin(time * speed * 1.4 + mh.phase * 1.5) * 5;
    mh.light.target.position.set(targetX, 0, targetZ);

    mh.cone.position.copy(mh.light.position);
    const dir = new THREE.Vector3().subVectors(mh.light.target.position, mh.light.position).normalize();
    mh.cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, -1, 0), dir);

    // Color cycling
    const hue = (time * 0.1 + i * 0.1) % 1;
    const color = new THREE.Color().setHSL(hue, 1, 0.5);
    mh.light.color = color;
    mh.light.intensity = params.movingHeadIntensity;
    mh.cone.material.color = color;
    if (mh.fixture.lens) mh.fixture.lens.material.color = color;
  });

  // Animate LED bars
  const ledSpeed = params.ledBarSpeed;
  barLights.forEach((bl) => {
    bl.bar.lights.forEach((led, i) => {
      const hue = (time * ledSpeed + i * 0.05 + bl.phase) % 1;
      const brightness = (Math.sin(time * 3 + i * 0.3 + bl.phase) + 1) / 2;
      const color = new THREE.Color().setHSL(hue, 1, 0.5 * brightness + 0.2);
      led.mesh.material.color = color;
      led.light.color = color;
      led.light.intensity = brightness * 3;
    });
  });

  // Blinder flash effect
  const blinderOn = Math.sin(time * params.blinderFlashRate) > 0.9;
  blinder.cells.forEach((cell) => {
    cell.light.intensity = blinderOn ? 100 : 0;
    cell.mesh.material.color.setHex(blinderOn ? 0xffffff : 0x333322);
  });

  // Animate spot light intensity
  spotLights.forEach((sl, i) => {
    const pulse = (Math.sin(time * 2 + i * 0.5) + 1) / 2;
    sl.light.intensity = params.spotIntensity * (0.6 + pulse * 0.4);
    sl.cone.material.opacity = 0.05 + pulse * 0.05;
  });

  // Haze drift
  const positions = haze.geometry.attributes.position.array;
  for (let i = 0; i < hazeCount; i++) {
    positions[i * 3 + 1] += 0.005;
    if (positions[i * 3 + 1] > 15) positions[i * 3 + 1] = 0;
  }
  haze.geometry.attributes.position.needsUpdate = true;

  // Camera auto-rotation
  if (params.autoRotate === 1) {
    objects.cameraAngle += params.cameraSpeed;
  } else {
    objects.cameraAngle = params.cameraAngle;
  }
  updateCamera(camera, params.cameraAngle);


}

function cleanup(objects) {
  if (objects.haze) {
    objects.haze.geometry.dispose();
    objects.hazeMat.dispose();
  }
}

